{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    vr = next(r for r, row in enumerate(grid) if all(v == 3 for v in row))
    vc = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))
    # Values by distance from the horizontal divider (row), then distance
    # from the vertical divider (column). The two sides of each divider mirror.
    rows = {
        1: [0, 4, 0, 4, 0, 4],
        2: [4, 4, 0, 4, 0, 4],
        3: [0, 0, 0, 4, 0, 4],
        4: [4, 4, 4, 4, 0, 4],
        5: [0, 0, 0, 0, 0, 4],
        6: [4, 4, 4, 4, 4, 4],
        7: [0, 0, 0, 0, 0, 0],
        8: [4, 4, 4, 4, 4, 4],
    }
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                continue
            y, x = abs(r - vr), abs(c - vc)
            if y == 0 or x == 0:
                continue
            if y in rows and x <= len(rows[y]):
                out[r][c] = rows[y][x - 1]
            else:
                out[r][c] = 4 if y % 2 == 0 else 0
    return out
